package greeter

import "testing"

func TestSlug(t *testing.T) {
	if got := Slug("Hello World"); got != "hello-world" {
		t.Fatalf("Slug(Hello World) = %q", got)
	}
	if got := Slug("  Hello World  "); got != "hello-world" {
		t.Fatalf("Slug(padded) = %q", got)
	}
	if got := Slug("a   b"); got != "a-b" {
		t.Fatalf("Slug(a   b) = %q", got)
	}
}
